static int do_main(int argc, char* argv[], char* envp[]) {
  // Allow thunderbird.exe to launch XULRunner apps via -app <application.ini>
  // Note that -app must be the *first* argument.
  const char* appDataFile = getenv("XUL_APP_FILE");
  if ((!appDataFile || !*appDataFile) && (argc > 1 && IsArg(argv[1], "app"))) {
    if (argc == 2) {
      Output("Incorrect number of arguments passed to -app");
      return 255;
    }
    appDataFile = argv[2];

    char appEnv[MAXPATHLEN];
    SprintfLiteral(appEnv, "XUL_APP_FILE=%s", argv[2]);
    if (putenv(strdup(appEnv))) {
      Output("Couldn't set %s.\n", appEnv);
      return 255;
    }
    argv[2] = argv[0];
    argv += 2;
    argc -= 2;
  } else if (argc > 1 && IsArg(argv[1], "xpcshell")) {
    for (int i = 1; i < argc; i++) {
      argv[i] = argv[i + 1];
    }

    XREShellData shellData;
#if defined(XP_WIN) && defined(MOZ_SANDBOX)
    shellData.sandboxBrokerServices =
        sandboxing::GetInitializedBrokerServices();
#endif

    return gBootstrap->XRE_XPCShellMain(--argc, argv, envp, &shellData);
  }

  BootstrapConfig config;

  if (appDataFile && *appDataFile) {
    config.appData = nullptr;
    config.appDataPath = appDataFile;
  } else {
    // no -app flag so we use the compiled-in app data
    config.appData = &sAppData;
    config.appDataPath = kDesktopFolder;
  }

#if defined(XP_WIN) && defined(MOZ_SANDBOX)
  sandbox::BrokerServices* brokerServices =
      sandboxing::GetInitializedBrokerServices();
  if (!brokerServices) {
    Output("Couldn't initialize the broker services.\n");
    return 255;
  }
  config.sandboxBrokerServices = brokerServices;
#endif

#ifdef LIBFUZZER
  if (getenv("FUZZER"))
    gBootstrap->XRE_LibFuzzerSetDriver(fuzzer::FuzzerDriver);
#endif

  // Note: FF needs to keep in sync with LauncherProcessWin,
  //       TB doesn't have that file.
  const char* acceptableParams[] = {"compose", "mail"};
  EnsureCommandlineSafe(argc, argv, acceptableParams);

#ifdef XP_WIN
  //  Allow the user to raise the number of files that may be open
  //  simultaneously by setting an environment variable.
  const char* mozMaxstdio = getenv("MOZ_MAXSTDIO");
  if (mozMaxstdio) {
    int limit = atoi(mozMaxstdio);
    int newLimit = -1;
    if (limit >= 3 && limit <= 8192) {
      newLimit = _setmaxstdio(limit);
    }
    if (newLimit != limit) {
      Output(
          "The open file limit could not be set from the MOZ_MAXSTDIO "
          "environment variable.\n");
    }
  }
#endif

  return gBootstrap->XRE_main(argc, argv, config);
}
